@page "/board"
@rendermode InteractiveServer
@inject ITaskService TaskService

<PageTitle>Kanban Board</PageTitle>

<h3 class="mb-3">Kanban Board</h3>

@if (isLoading)
{
    <div class="text-center py-5">
        <div class="spinner-border" role="status">
            <span class="visually-hidden">Loading...</span>
        </div>
        <p class="mt-2">Loading tasks...</p>
    </div>
}
else if (errorMessage is not null)
{
    <div class="alert alert-danger" role="alert">
        <strong>Error:</strong> @errorMessage
    </div>
}
else
{
    <BoardStats Total="allTasks.Count"
                TodoCount="TodoTasks.Count"
                InProgressCount="InProgressTasks.Count"
                DoneCount="DoneTasks.Count"
                OverdueCount="OverdueCount" />

    <BoardSearchBar SearchText="@searchText" SearchTextChanged="OnSearchChanged" />

    <div class="row g-3">
        <BoardColumn ColumnName="To Do"
                     Tasks="TodoTasks"
                     CanMoveLeft="false"
                     CanMoveRight="true"
                     OnMoveRight="MoveToInProgress"
                     OnAddTask="model => AddTask(model, \"To Do\")" />

        <BoardColumn ColumnName="In Progress"
                     Tasks="InProgressTasks"
                     CanMoveLeft="true"
                     CanMoveRight="true"
                     OnMoveLeft="MoveToTodo"
                     OnMoveRight="MoveToDone"
                     OnAddTask="model => AddTask(model, \"In Progress\")" />

        <BoardColumn ColumnName="Done"
                     Tasks="DoneTasks"
                     CanMoveLeft="true"
                     CanMoveRight="false"
                     OnMoveLeft="MoveToInProgress2"
                     OnAddTask="model => AddTask(model, \"Done\")" />
    </div>
}

@code {
    private List<TaskItem> allTasks = new();
    private string searchText = string.Empty;
    private bool isLoading = true;
    private string? errorMessage;

    private List<TaskItem> FilteredTasks => string.IsNullOrWhiteSpace(searchText)
        ? allTasks
        : allTasks.Where(t => t.Title.Contains(searchText, StringComparison.OrdinalIgnoreCase)).ToList();

    private List<TaskItem> TodoTasks => FilteredTasks.Where(t => t.Status == "To Do").ToList();
    private List<TaskItem> InProgressTasks => FilteredTasks.Where(t => t.Status == "In Progress").ToList();
    private List<TaskItem> DoneTasks => FilteredTasks.Where(t => t.Status == "Done").ToList();
    private int OverdueCount => allTasks.Count(t => t.DueDate < DateTime.Today);

    protected override async Task OnInitializedAsync()
    {
        try
        {
            allTasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            errorMessage = ex.Message;
        }
        finally
        {
            isLoading = false;
        }
    }

    private void OnSearchChanged(string value)
    {
        searchText = value;
    }

    private async Task MoveTask(int taskId, string newStatus)
    {
        try
        {
            await TaskService.UpdateTaskStatusAsync(taskId, newStatus);
            var task = allTasks.First(t => t.Id == taskId);
            var index = allTasks.IndexOf(task);
            allTasks[index] = task with { Status = newStatus };
        }
        catch (Exception ex)
        {
            errorMessage = ex.Message;
        }
    }

    private Task MoveToInProgress(int taskId) => MoveTask(taskId, "In Progress");
    private Task MoveToTodo(int taskId) => MoveTask(taskId, "To Do");
    private Task MoveToDone(int taskId) => MoveTask(taskId, "Done");
    private Task MoveToInProgress2(int taskId) => MoveTask(taskId, "In Progress");

    private async Task AddTask(AddTaskForm.NewTaskModel model, string status)
    {
        try
        {
            var newTask = await TaskService.CreateTaskAsync(model.Title, model.Assignee, model.Priority, model.DueDate);
            // CreateTaskAsync returns the task with its default status; update to target column if different
            if (newTask.Status != status)
            {
                await TaskService.UpdateTaskStatusAsync(newTask.Id, status);
                newTask = newTask with { Status = status };
            }
            allTasks.Add(newTask);
        }
        catch (Exception ex)
        {
            errorMessage = ex.Message;
        }
    }
}

